/**
 * Ambient types for the vendored Emscripten factory at
 * `@augmem/cortext-wasm/module`.
 *
 * The factory is generated by the engine monorepo `./build-wasm.sh` and copied
 * into `assets/` via `npm run vendor:wasm`. Types here are self-contained so
 * consumers do not depend on `dist/` being present at type-resolution time.
 */

declare module "@augmem/cortext-wasm/module" {
  /** Minimal Emscripten module shape used by CortextWasm. */
  export interface CortextEmscriptenModule {
    FS: {
      mkdir(path: string): void;
      writeFile(path: string, data: Uint8Array | string): void;
    };
    HEAPU8: Uint8Array;
    HEAPF32: Float32Array;
    _malloc(size: number): number;
    _free(ptr: number): void;
    lengthBytesUTF8(str: string): number;
    stringToUTF8(str: string, outPtr: number, maxBytesToWrite: number): number;
    UTF8ToString(ptr: number): string;
    _cortext_create(
      focus: number,
      sensitivity: number,
      stability: number,
      dbPathPtr: number
    ): number;
    _cortext_free(handle: number): void;
    _cortext_reset(handle: number): number;
    _cortext_flush(handle: number): number;
    _cortext_consolidate(handle: number): number;
    _cortext_version(): number;
    _cortext_last_error(): number;
    _cortext_string_free(ptr: number): void;
    _cortext_embed_text_json(handle: number, textPtr: number): number;
    _cortext_embed_audio_json(
      handle: number,
      pcmPtr: number,
      sampleCount: number
    ): number;
    _cortext_embed_image_json(
      handle: number,
      dataPtr: number,
      width: number,
      height: number,
      channels: number
    ): number;
    _cortext_wasm_process_text_json(
      handle: number,
      textPtr: number,
      sourcePtr: number,
      includeEmbedding: number,
      retention: number
    ): number;
    _cortext_process_text_with_media_json_with_options(
      handle: number,
      textPtr: number,
      sourcePtr: number,
      mediaPtr: number,
      optionsPtr: number
    ): number;
  }

  export type CortextModuleFactory = (
    options?: Record<string, unknown>
  ) => Promise<CortextEmscriptenModule>;

  const createCortextModule: CortextModuleFactory;
  export default createCortextModule;
}
